-- Table structure for t_entity
-- ----------------------------
DROP TABLE IF EXISTS "public"."t_entity";
CREATE TABLE "public"."t_entity" (
  "id" int8 NOT NULL DEFAULT nextval('t_entity_id_seq'::regclass),
  "domain" int2 NOT NULL,
  "entity_type" int2 NOT NULL,
  "parent_id" int8,
  "owner_user_id" int8,
  "name" varchar(128) COLLATE "pg_catalog"."default",
  "title" varchar(255) COLLATE "pg_catalog"."default",
  "description" text COLLATE "pg_catalog"."default",
  "category" varchar(100) COLLATE "pg_catalog"."default",
  "thumbnail" text COLLATE "pg_catalog"."default",
  "downloads" int4 DEFAULT 0,
  "rating_tpl" numeric(3,2) DEFAULT 0,
  "likes" int4 DEFAULT 0,
  "rating_cmt" int2,
  "tag_name" varchar(50) COLLATE "pg_catalog"."default",
  "content_md" text COLLATE "pg_catalog"."default",
  "content_html" text COLLATE "pg_catalog"."default",
  "status" int2 DEFAULT 1,
  "is_pinned" bool DEFAULT false,
  "view_count" int4,
  "word_count" int4,
  "color" varchar(7) COLLATE "pg_catalog"."default",
  "sort_order" int4,
  "origin_template_entity_id" int8,
  "create_time" timestamp(6) DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp(6) DEFAULT CURRENT_TIMESTAMP
)
;
COMMENT ON TABLE "public"."t_entity" IS '统一单表：domain 1=模板域, 2=笔记域；entity_type 1/2/3 见各域定义';

