-- ----------------------------
-- Function structure for fn_cleanup_documents_on_kb_delete
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."fn_cleanup_documents_on_kb_delete"();
CREATE OR REPLACE FUNCTION "public"."fn_cleanup_documents_on_kb_delete"()
  RETURNS "pg_catalog"."trigger" AS $BODY$
BEGIN
  DELETE FROM public.documents
    WHERE knowledge_base_type = 2
      AND knowledge_base_id = OLD.id;
  RETURN OLD;
END $BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;

-- ----------------------------
-- Function structure for fn_migration_v2_ai_settings_down
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."fn_migration_v2_ai_settings_down"();
CREATE OR REPLACE FUNCTION "public"."fn_migration_v2_ai_settings_down"()
  RETURNS "pg_catalog"."void" AS $BODY$
    BEGIN
      -- 删除触发器
      IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='trg_user_ai_settings_update_time') THEN
        DROP TRIGGER trg_user_ai_settings_update_time ON public.t_user_ai_settings;
      END IF;
      -- 删除外键与索引
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_user_ai_settings_user') THEN
        ALTER TABLE public.t_user_ai_settings DROP CONSTRAINT fk_user_ai_settings_user;
      END IF;
      IF EXISTS (SELECT 1 FROM pg_class WHERE relname='idx_user_ai_settings_user') THEN
        DROP INDEX IF EXISTS idx_user_ai_settings_user;
      END IF;
      -- 删除唯一约束（随表一同删除，这里容错）
      -- DROP INDEX IF EXISTS uk_user_ai_settings;
      -- 删除表
      DROP TABLE IF EXISTS public.t_user_ai_settings;
    END
    $BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;

-- ----------------------------
-- Function structure for fn_set_update_time
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."fn_set_update_time"();
CREATE OR REPLACE FUNCTION "public"."fn_set_update_time"()
  RETURNS "pg_catalog"."trigger" AS $BODY$
BEGIN
  IF TG_ARGV[0] = 'update_time' THEN
    NEW.update_time := CURRENT_TIMESTAMP;
  ELSIF TG_ARGV[0] = 'updated_at' THEN
    NEW.updated_at := CURRENT_TIMESTAMP;
  END IF;
  RETURN NEW;
END $BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;

