-- ----------------------------
-- View structure for v_t_template
-- ----------------------------
DROP VIEW IF EXISTS "public"."v_t_template";
CREATE VIEW "public"."v_t_template" AS  SELECT id,
    title,
    description,
    category,
    thumbnail,
    downloads,
    rating_tpl AS rating,
    ( SELECT t_entity.owner_user_id) AS author_id,
    create_time,
    update_time
   FROM t_entity
  WHERE domain = 1 AND entity_type = 1;

-- ----------------------------
-- View structure for v_t_template_tag
-- ----------------------------
DROP VIEW IF EXISTS "public"."v_t_template_tag";
CREATE VIEW "public"."v_t_template_tag" AS  SELECT id,
    parent_id AS template_id,
    tag_name,
    create_time
   FROM t_entity
  WHERE domain = 1 AND entity_type = 2;

-- ----------------------------
-- View structure for v_t_template_comment
-- ----------------------------
DROP VIEW IF EXISTS "public"."v_t_template_comment";
CREATE VIEW "public"."v_t_template_comment" AS  SELECT id,
    parent_id AS template_id,
    owner_user_id AS user_id,
    content_md AS content,
    rating_cmt AS rating,
    likes,
    create_time
   FROM t_entity
  WHERE domain = 1 AND entity_type = 3;

-- ----------------------------
-- View structure for v_t_notebook
-- ----------------------------
DROP VIEW IF EXISTS "public"."v_t_notebook";
CREATE VIEW "public"."v_t_notebook" AS  SELECT id,
    name,
    description,
    color,
    owner_user_id AS user_id,
    create_time,
    update_time,
    sort_order
   FROM t_entity
  WHERE domain = 2 AND entity_type = 1;

-- ----------------------------
-- View structure for v_t_note
-- ----------------------------
DROP VIEW IF EXISTS "public"."v_t_note";
CREATE VIEW "public"."v_t_note" AS  SELECT id,
    title,
    content_md,
    content_html,
    parent_id AS notebook_id,
    owner_user_id AS user_id,
    is_pinned,
    status,
    create_time,
    update_time,
    view_count,
    word_count,
    origin_template_entity_id AS origin_template_id
   FROM t_entity
  WHERE domain = 2 AND entity_type = 2;

-- ----------------------------
-- View structure for v_t_note_tag
-- ----------------------------
DROP VIEW IF EXISTS "public"."v_t_note_tag";
CREATE VIEW "public"."v_t_note_tag" AS  SELECT id,
    parent_id AS note_id,
    tag_name,
    create_time
   FROM t_entity
  WHERE domain = 2 AND entity_type = 3;

